result={'profiles':[],'errors':[],'scope':'Packaged application / synthetic offline provider. Not live-market verification.'}
with sync_playwright() as p:
 b=p.chromium.launch(executable_path=os.environ['CHROMIUM_PATH'],args=['--no-sandbox']);page=b.new_page(viewport={'width':1440,'height':1000});page.on('pageerror',lambda e:result['errors'].append(str(e)));requests=[];page.on('request',lambda r:requests.append(r.url) if '/api/research/evaluate' in r.url else None)
 page.route('https://**/*',lambda r:r.abort());page.goto(os.environ['TEST_URL']);page.wait_for_function('window.THNCommand?.state().fresh&&window.THNConfidence&&THNDecision.brief()&&THNMarketTerminal.catalog().length')
 page.add_script_tag(path=os.environ['AXE_PATH']);saved=page.evaluate('JSON.stringify(THNLibrary.entries())');page.evaluate('window.__trustChart=THNResearch.chart;window.__trustForm=document.getElementById("qBacktestForm")')
 expect(page.locator('#commandTrust')).to_have_attribute('data-probability','unavailable');expect(page.locator('#trustSignals')).to_contain_text('Not available');expect(page.locator('#trustHistoricalEvidence')).to_contain_text('Historical validation unavailable')
 page.locator('#trustReviewAction').click();expect(page.locator('#trustTitle')).to_be_focused();page.locator('[data-trust=score]').click();expect(page.locator('#trustConfluenceTitle')).to_be_focused();expect(page.locator('#trustScoreEvidence')).to_contain_text('cannot reproduce exactly');assert page.locator('.trust-school-list article').count()==8
 page.locator('#trustConfluenceTitle').press('Escape');expect(page.locator('[data-trust=score]')).to_be_focused()
