 pending=[];page.route('**/api/research/evaluate',lambda r:pending.append(r));page.locator('#qRun').click();page.wait_for_function('THNConfidence.review().testStatus==="running"');expect(page.locator('#commandTrust')).to_have_attribute('data-validation','running');page.locator('#qParam_spread').fill('6');route=pending.pop();response=route.fetch();route.fulfill(response=response);page.wait_for_function('THNConfidence.review().testStatus==="changed"');expect(page.locator('#commandTrust')).to_have_attribute('data-validation','changed');expect(page.locator('#trustValidationHost')).to_contain_text('Retained report, not current validation');page.unroute('**/api/research/evaluate')
 page.locator('#qRun').click();page.wait_for_function('THNConfidence.review().testStatus==="complete"');expect(page.locator('#commandTrust')).to_have_attribute('data-validation','current');assert len(requests)==2
