 first=page.locator('#trustValidationHost [data-validation-check]').nth(0);first.locator('summary').click();first.locator('[data-validation-control]').click();expect(page.locator('#qMinimumTrades')).to_be_focused();assert page.locator('#trustTestHost #qBacktestForm').count()==1
 page.locator('#trustTestTitle').press('Escape');expect(page.locator('#trustHeader [data-trust=test]')).to_be_focused();assert page.locator('#studioLabGrid #qBacktestForm').count()==1
 page.locator('#trustHeader [data-trust=test]').click();page.locator('.nav-stack [data-view=portfolio]').click();expect(page.locator('#studioLabGrid #qRun')).to_be_visible();assert page.locator('#qBacktestForm').evaluate('(e)=>e===window.__trustForm');page.locator('.nav-stack [data-view=dashboard]').click();expect(page.locator('#trustTestHost #qRun')).to_be_visible()
 page.route('**/api/research/evaluate',lambda r:r.fulfill(status=503,json={'ok':False,'code':'MARKET_DATA_UNAVAILABLE'}));page.locator('#qRun').click();page.wait_for_function('THNConfidence.review().testStatus==="failed"');expect(page.locator('#commandTrust')).to_have_attribute('data-validation','failed');expect(page.locator('#trustValidationHost')).to_contain_text('Retained report, not current validation');page.unroute('**/api/research/evaluate')
 # All new regions are genuinely rendered across the supported layouts/languages/themes.
 for width,lang,theme in itertools.product([1440,1024,768,390,320],['en','ar'],['dark','light']):
  page.set_viewport_size({'width':width,'height':1000});page.locator('.terminal-topbar [data-language='+lang+']').click();page.evaluate('(t)=>document.documentElement.dataset.theme=t',theme);page.wait_for_function('(lang)=>document.documentElement.lang===lang',arg=lang)
  page.locator('#trustCandidate').evaluate('(e)=>e.open=true');page.locator('#trustConfluence').evaluate('(e)=>e.open=true');assert page.evaluate('document.documentElement.scrollWidth<=innerWidth+1'),(width,lang,theme)
  expect(page.locator('[data-trust-confluence]')).to_have_attribute('dir','ltr');assert page.locator('#trustScoreEvidence .trust-fields bdi').evaluate_all('(nodes)=>nodes.every(n=>getComputedStyle(n).direction==="ltr")');assert page.evaluate('THNResearch.chart===window.__trustChart');assert page.locator('#qBacktestForm').count()==1;assert page.evaluate('JSON.stringify(THNLibrary.entries())')==saved
  violations=page.evaluate('async()=> (await axe.run(document.querySelector("#commandTrust"),{runOnly:{type:"tag",values:["wcag2a","wcag2aa","wcag21aa"]}})).violations.map(v=>({id:v.id,nodes:v.nodes.map(n=>n.target)}))');assert not violations,(width,lang,theme,violations)
  result['profiles'].append([width,lang,theme])
 page.set_viewport_size({'width':1440,'height':1000});page.locator('.terminal-topbar [data-language=en]').click()
