 page.evaluate('THNCommand.pick("GBPUSD")');page.wait_for_function('THNContext.get().symbol==="GBPUSD"&&THNCommand.state().fresh');expect(page.locator('#trustValidationHost [data-validation-check]')).to_have_count(0);expect(page.locator('#trustHistoricalEvidence')).to_contain_text('Historical validation unavailable')
 def stale(route):
  response=route.fetch();data=response.json();data['provenance']['status']='stale';route.fulfill(response=response,json=data)
 page.route('**/api/research/series?**',stale);page.locator('#qRefresh').click();page.wait_for_function('THNCommand.state().phase==="stale"');expect(page.locator('#commandTrust')).to_have_attribute('data-candidate','unavailable');expect(page.locator('.trust-school-list article')).to_have_count(0);expect(page.locator('#trustSignals')).to_contain_text('Not current');page.unroute('**/api/research/series?**')
 page.route('**/api/research/series?**',lambda r:r.fulfill(status=503,json={'ok':False,'code':'MARKET_DATA_UNAVAILABLE'}));page.locator('#qRefresh').click();page.wait_for_function('THNResearch.series()===null');expect(page.locator('#commandTrust')).to_have_attribute('data-candidate','unavailable');assert page.evaluate('JSON.stringify(THNLibrary.entries())')==saved
 assert not result['errors'],result['errors'];b.close()
